class Solution:
    def totalBeauty(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        from collections import defaultdict
        V = max(nums)
        pos = defaultdict(list)
        for i, v in enumerate(nums):
            pos[v].append(i)
        phi = list(range(V + 1))
        for p in range(2, V + 1):
            if phi[p] == p:
                for j in range(p, V + 1, p):
                    phi[j] -= phi[j] // p
        ans = 0
        for d in range(1, V + 1):
            idxs = []
            for m in range(d, V + 1, d):
                idxs.extend(pos[m])
            if not idxs:
                continue
            idxs.sort()
            comp = sorted(set(nums[i] // d for i in idxs))
            rank = {v: i + 1 for i, v in enumerate(comp)}
            m = len(comp)
            bit = [0] * (m + 1)
            def up(i, v):
                while i <= m:
                    bit[i] = (bit[i] + v) % MOD
                    i += i & -i
            def q(i):
                s = 0
                while i > 0:
                    s = (s + bit[i]) % MOD
                    i -= i & -i
                return s
            tot = 0
            for i in idxs:
                r = rank[nums[i] // d]
                add = (q(r - 1) + 1) % MOD
                up(r, add)
                tot = (tot + add) % MOD
            ans = (ans + phi[d] * tot) % MOD
        return ans

