class Solution {
public:
    int totalBeauty(vector<int>& nums) {
        const long long MOD = 1e9 + 7;
        int n = nums.size(), V = *max_element(nums.begin(), nums.end());
        vector<vector<int>> pos(V + 1);
        for (int i = 0; i < n; i++) pos[nums[i]].push_back(i);
        vector<long long> phi(V + 1);
        iota(phi.begin(), phi.end(), 0);
        for (int p = 2; p <= V; p++)
            if (phi[p] == p)
                for (int j = p; j <= V; j += p) phi[j] -= phi[j] / p;
        long long ans = 0;
        vector<int> bit;
        for (int d = 1; d <= V; d++) {
            vector<int> idxs;
            for (int m = d; m <= V; m += d)
                for (int i : pos[m]) idxs.push_back(i);
            if (idxs.empty()) continue;
            sort(idxs.begin(), idxs.end());
            vector<int> vals;
            for (int i : idxs) vals.push_back(nums[i] / d);
            sort(vals.begin(), vals.end());
            vals.erase(unique(vals.begin(), vals.end()), vals.end());
            int m = vals.size();
            bit.assign(m + 1, 0);
            auto up = [&](int i, long long v) { for (; i <= m; i += i & -i) bit[i] = (bit[i] + v) % MOD; };
            auto q = [&](int i) { long long s = 0; for (; i > 0; i -= i & -i) s = (s + bit[i]) % MOD; return s; };
            long long tot = 0;
            for (int i : idxs) {
                int r = lower_bound(vals.begin(), vals.end(), nums[i] / d) - vals.begin() + 1;
                long long add = (q(r - 1) + 1) % MOD;
                up(r, add);
                tot = (tot + add) % MOD;
            }
            ans = (ans + phi[d] * tot) % MOD;
        }
        return (int)ans;
    }
};

