class Solution {
    public int totalBeauty(int[] nums) {
        final long MOD = 1_000_000_007L;
        int n = nums.length, V = 0;
        for (int v : nums) V = Math.max(V, v);
        List<List<Integer>> pos = new ArrayList<>();
        for (int i = 0; i <= V; i++) pos.add(new ArrayList<>());
        for (int i = 0; i < n; i++) pos.get(nums[i]).add(i);
        long[] phi = new long[V + 1];
        for (int i = 0; i <= V; i++) phi[i] = i;
        for (int p = 2; p <= V; p++)
            if (phi[p] == p)
                for (int j = p; j <= V; j += p) phi[j] -= phi[j] / p;
        long ans = 0;
        for (int d = 1; d <= V; d++) {
            List<Integer> idxs = new ArrayList<>();
            for (int m = d; m <= V; m += d) idxs.addAll(pos.get(m));
            if (idxs.isEmpty()) continue;
            Collections.sort(idxs);
            TreeSet<Integer> set = new TreeSet<>();
            for (int i : idxs) set.add(nums[i] / d);
            List<Integer> vals = new ArrayList<>(set);
            int m = vals.size();
            long[] bit = new long[m + 1];
            java.util.function.BiConsumer<Integer,Long> up = (i, v) -> { for (; i <= m; i += i & -i) bit[i] = (bit[i] + v) % MOD; };
            java.util.function.IntFunction<Long> q = i -> { long s = 0; for (; i > 0; i -= i & -i) s = (s + bit[i]) % MOD; return s; };
            long tot = 0;
            for (int i : idxs) {
                int r = Collections.binarySearch(vals, nums[i] / d) + 1;
                long add = (q.apply(r - 1) + 1) % MOD;
                up.accept(r, add);
                tot = (tot + add) % MOD;
            }
            ans = (ans + phi[d] * tot) % MOD;
        }
        return (int) ans;
    }
}

