var totalBeauty = function(nums) {
    const MOD = 1e9 + 7;
    const n = nums.length, V = Math.max(...nums);
    const pos = Array.from({length: V + 1}, () => []);
    nums.forEach((v, i) => pos[v].push(i));
    const phi = Array.from({length: V + 1}, (_, i) => i);
    for (let p = 2; p <= V; p++)
        if (phi[p] === p)
            for (let j = p; j <= V; j += p) phi[j] -= Math.floor(phi[j] / p);
    let ans = 0;
    for (let d = 1; d <= V; d++) {
        const idxs = [];
        for (let m = d; m <= V; m += d) idxs.push(...pos[m]);
        if (!idxs.length) continue;
        idxs.sort((a, b) => a - b);
        const vals = [...new Set(idxs.map(i => Math.floor(nums[i] / d)))].sort((a, b) => a - b);
        const m = vals.length;
        const bit = Array(m + 1).fill(0);
        const up = (i, v) => { for (; i <= m; i += i & -i) bit[i] = (bit[i] + v) % MOD; };
        const q = (i) => { let s = 0; for (; i > 0; i -= i & -i) s = (s + bit[i]) % MOD; return s; };
        let tot = 0;
        for (const i of idxs) {
            const r = vals.indexOf(Math.floor(nums[i] / d)) + 1;
            const add = (q(r - 1) + 1) % MOD;
            up(r, add);
            tot = (tot + add) % MOD;
        }
        ans = (ans + phi[d] * tot) % MOD;
    }
    return ans;
};
